package com.fasterxml.jackson.core.sym;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.util.InternCache;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ByteQuadsCanonicalizer.calcHash(int)
 */
public class ByteQuadsCanonicalizer_calcHash_TriageGen2Test {

    @Test
    public void testCalcHashWithZero() {
        // Using createRoot() which initializes with a default seed
        ByteQuadsCanonicalizer canonicalizer = ByteQuadsCanonicalizer.createRoot();
        int seed = canonicalizer.hashSeed();

        int q1 = 0;
        // Manual calculation for verification:
        // hash = 0 ^ seed = seed
        // hash += (hash >>> 16)
        // hash ^= (hash >>> 12)
        int expected = calculateExpected(0, seed);

        assertEquals("Hash of 0 should match expected transformation", expected, canonicalizer.calcHash(q1));
    }









    /**
     * Helper to replicate the logic for assertion verification.
     */
    private int calculateExpected(int q1, int seed) {
        int hash = q1 ^ seed;
        hash += (hash >>> 16);
        hash ^= (hash >>> 12);
        return hash;
    }
}

