/**
 * Unit tests for ByteQuadsCanonicalizer.calcHash(int)
 */
public class ByteQuadsCanonicalizer_calcHash_TriageGen2Test {









    @Test
    public void testCalcHashWithDifferentSeeds() {
        // Since createRoot(int seed) is protected, we can't access it directly from a standard test 
        // unless we are in the same package. Since our test is in the same package, we can use it.
        int seed1 = 0x12345678;
        int seed2 = 0x87654321;

        ByteQuadsCanonicalizer canon1 = ByteQuadsCanonicalizer.createRoot(seed1);
        ByteQuadsCanonicalizer canon2 = ByteQuadsCanonicalizer.createRoot(seed2);

        int q1 = 99;

        assertNotEquals("Hashes with different seeds should likely differ", 
            canon1.calcHash(q1), canon2.calcHash(q1));
    }

    /**
     * Helper to replicate the logic for assertion verification.
     */
    private int calculateExpected(int q1, int seed) {
        int hash = q1 ^ seed;
        hash += (hash >>> 16);
        hash ^= (hash >>> 12);
        return hash;
    }
}
